const products = [
  { id: 'shirt', name: '셔츠' },
  { id: 'hat', name: '모자' },
  { id: 'shoes', name: '신발' },
];

function ProductList() {
  return (
    <ul className="list">
      {products.map((product) => (
        <li key={product.id}>{product.name}</li>
      ))}
    </ul>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<ProductList />);

